(7224952, 1114620, 150277, '<td valign="top">I like the scene and the green of the trees, but that orange sky seems a bit unreal.</td>', 'I like the scene and the green of the trees, but that orange sky seems a bit unreal.', '2014-06-05 15:18:19.000000', NULL, 1),
(7224953, 1115373, 150277, '<td valign="top">What a view.  I love that you got part of the car, it puts it in perspective.</td>', 'What a view.  I love that you got part of the car, it puts it in perspective.', '2014-06-05 15:21:03.000000', NULL, 1),
(7224954, 1115206, 150277, '<td valign="top">Beautiful capture of the area.</td>', 'Beautiful capture of the area.', '2014-06-05 15:21:17.000000', NULL, 1),
(7224955, 1115457, 150277, '<td valign="top">I see a great richness and vibrancy to this park.</td>', 'I see a great richness and vibrancy to this park.', '2014-06-05 15:22:29.000000', NULL, 1),
(7224956, 1115267, 150277, '<td valign="top">I thought this photo was well done.  I found it interesting and well composed.  Thanks for sharing.</td>', 'I thought this photo was well done.  I found it interesting and well composed.  Thanks for sharing.', '2014-06-05 15:23:18.000000', NULL, 1),
(7224957, 1115292, 150277, '<td valign="top">What an odd perspective you captured. I  really enjoyed this image.  Well done.</td>', 'What an odd perspective you captured. I  really enjoyed this image.  Well done.', '2014-06-05 15:23:45.000000', NULL, 1),
(7224958, 1115209, 150277, '<td valign="top">Capturing that leap, great idea.  I enjoyed the uniqueness of the photo and the joy I feel from that young man''s jump.</td>', 'Capturing that leap, great idea.  I enjoyed the uniqueness of the photo and the joy I feel from that young man''s jump.', '2014-06-05 15:24:33.000000', NULL, 1),
(7224971, 1115575, 142345, '<td valign="top">I like the added symmetry with the reflection</td>', 'I like the added symmetry with the reflection', '2014-06-05 16:13:22.000000', NULL, 1),
(7224976, 1115403, 142345, '<td valign="top">I like the framing with the leaves, wish it was a bit sharper though.</td>', 'I like the framing with the leaves, wish it was a bit sharper though.', '2014-06-05 16:25:49.000000', NULL, 1),
(7224979, 1115447, 142345, '<td valign="top">Love the vibrant colors</td>', 'Love the vibrant colors', '2014-06-05 16:30:44.000000', NULL, 1),
(7224982, 1115430, 142345, '<td valign="top">This is very busy and distracting to me.</td>', 'This is very busy and distracting to me.', '2014-06-05 16:35:27.000000', NULL, 1),
(7224983, 1115599, 142345, '<td valign="top">Nice use of patterns and leading lines.</td>', 'Nice use of patterns and leading lines.', '2014-06-05 16:36:22.000000', NULL, 1),
