(7224985, 1115210, 142345, '<td valign="top">Looks like there is fuzz on the lens between the 2nd and 3rd tree on the right. Also, I wish it was sharper...I feel a lot of texture was lost in the leading lines and in the trees. Enjoy the symmetry though.</td>', 'Looks like there is fuzz on the lens between the 2nd and 3rd tree on the right. Also, I wish it was sharper...I feel a lot of texture was lost in the leading lines and in the trees. Enjoy the symmetry though.', '2014-06-05 16:43:58.000000', NULL, 1),
(7224986, 1115372, 142345, '<td valign="top">One of my favorite parks, great shot.</td>', 'One of my favorite parks, great shot.', '2014-06-05 16:45:37.000000', NULL, 1),
(7225914, 1115206, 114225, '<td valign="top">I miss the Redwoods.</td>', 'I miss the Redwoods.', '2014-06-08 18:33:53.000000', NULL, 1),
(7225950, 1115532, 58634, '<td valign="top">Personally I would''ve preferred a tighter crop, especially from the top but wow! what a moment to capture!</td>', 'Personally I would''ve preferred a tighter crop, especially from the top but wow! what a moment to capture!', '2014-06-08 19:48:52.000000', NULL, 1),
(7225951, 1115176, 58634, '<td valign="top">Hmm, ironic that the only person that looks happy here is the conductor.</td>', 'Hmm, ironic that the only person that looks happy here is the conductor.', '2014-06-08 19:49:36.000000', NULL, 1),
(7225953, 1115561, 58634, '<td valign="top">The flow of the water is so tender here.</td>', 'The flow of the water is so tender here.', '2014-06-08 19:51:00.000000', NULL, 1),
(7225955, 1115224, 58634, '<td valign="top">Brilliant image. From the contrasts, to the mimimalism, to the scene captured, to the sharpness yet blurriness at the same time. Exceptional.</td>', 'Brilliant image. From the contrasts, to the mimimalism, to the scene captured, to the sharpness yet blurriness at the same time. Exceptional.', '2014-06-08 19:52:25.000000', NULL, 1),
